Here is the root cause:
The function `ceph_mdsc_build_path()` does not initialize the `ceph_path_info` structure on error paths, but all callers unconditionally call `ceph_mdsc_free_path_info()` afterward, leading to use of uninitialized memory, potentially causing slab corruption or crashes.

Here is the patch:
  */
 int ceph_open(struct inode *inode, struct file *file)
 {
 	struct ceph_inode_info *ci = ceph_inode(inode);
 	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(inode->i_sb);
 	struct ceph_client *cl = fsc->client;
 	struct ceph_mds_client *mdsc = fsc->mdsc;
 	struct ceph_mds_request *req;
 	struct ceph_file_info *fi = file->private_data;
 	int err;
 	int flags, fmode, wanted;
 	struct dentry *dentry;
 	char *path;
 	bool do_sync = false;
 	int mask = MAY_READ;

 	if (fi) {
 		doutc(cl, "file %p is already opened\n", file);
 		return 0;
 	}

 	/* filter out O_CREAT|O_EXCL; vfs did that already.  yuck. */
 	flags = file->f_flags & ~(O_CREAT|O_EXCL);
 	if (S_ISDIR(inode->i_mode)) {
 		flags = O_DIRECTORY;  /* mds likes to know */
 	} else if (S_ISREG(inode->i_mode)) {
 		err = fscrypt_file_open(inode, file);
 		if (err)
 			return err;
 	}

 	doutc(cl, "%p %llx.%llx file %p flags %d (%d)\n", inode,
 	      ceph_vinop(inode), file, flags, file->f_flags);
 	fmode = ceph_flags_to_mode(flags);
 	wanted = ceph_caps_for_mode(fmode);

 	if (fmode & CEPH_FILE_MODE_WR)
 		mask |= MAY_WRITE;
 	dentry = d_find_alias(inode);
 	if (!dentry) {
 		do_sync = true;
 	} else {
-		struct ceph_path_info path_info;
+		struct ceph_path_info path_info = {0};
 		path = ceph_mdsc_build_path(mdsc, dentry, &path_info, 0);
 		if (IS_ERR(path)) {
 			do_sync = true;
 			err = 0;
 		} else {
 			err = ceph_mds_check_access(mdsc, path, mask);
 		}
 		ceph_mdsc_free_path_info(&path_info);
 		dput(dentry);

 		/* For none EACCES cases will let the MDS do the mds auth check */
 		if (err == -EACCES) {
 			return err;
 		} else if (err < 0) {
 			do_sync = true;
 			err = 0;
 		}
 	}

 	/* snapped files are read-only */
 	if (ceph_snap(inode) != CEPH_NOSNAP && (file->f_mode & FMODE_WRITE))
 		return -EROFS;

 	/* trivially open snapdir */
 	if (ceph_snap(inode) == CEPH_SNAPDIR) {
 		return ceph_init_file(inode, file, fmode);
 	}

 	/*
 	 * No need to block if we have caps on the auth MDS (for
 	 * write) or any MDS (for read).  Update wanted set
 	 * asynchronously.
 	 */
 	spin_lock(&ci->i_ceph_lock);
 	if (!do_sync && __ceph_is_any_real_caps(ci) &&
 	    (((fmode & CEPH_FILE_MODE_WR) == 0) || ci->i_auth_cap)) {
 		int mds_wanted = __ceph_caps_mds_wanted(ci, true);
 		int issued = __ceph_caps_issued(ci, NULL);

 		doutc(cl, "open %p fmode %d want %s issued %s using existing\n",
 		      inode, fmode, ceph_cap_string(wanted),
 		      ceph_cap_string(issued));
 		__ceph_touch_fmode(ci, mdsc, fmode);
 		spin_unlock(&ci->i_ceph_lock);

